INSERT INTO `disc_replies` VALUES (25,25,24,'test',NULL,'2025-03-20 19:19:45','2025-03-20 19:19:45'),(38,39,16,'halo haloo',NULL,'2025-03-25 01:49:35','2025-03-25 01:49:35'),(39,38,16,'haloo haloo',NULL,'2025-03-25 01:49:44','2025-03-25 01:49:44'),(40,34,2,'Halo juga, Panji. 👋',NULL,'2025-03-26 01:23:40','2025-03-26 01:23:40'),(41,35,2,'Halo juga, Daniel. 👋',NULL,'2025-03-26 01:23:59','2025-03-26 01:23:59'),(42,37,2,'Selamat datang, David',NULL,'2025-03-26 01:24:25','2025-03-26 01:24:25'),(43,28,2,'Ya, Wahyu pemrograman prosedural dan model Waterfall memang sama-sama memiliki pendekatan yang berurutan, tetapi konsepnya berbeda.Pemrograman prosedural berfokus pada bagaimana program dijalankan, menggunakan fungsi atau prosedur yang dieksekusi satu per satu secara sistematis. Model Waterfall, di sisi lain, adalah metodologi pengembangan perangkat lunak, di mana setiap fase (analisis, desain, coding, testing, dll.) harus diselesaikan sebelum beralih ke tahap berikutnya. Ini lebih ke cara mengelola proyek, bukan cara menulis kode.Jadi, meskipun sama-sama terstruktur dan berurutan, pemrograman prosedural berbicara tentang cara program berjalan, sedangkan Waterfall berbicara tentang cara software dikembangkan.',NULL,'2025-03-26 01:29:19','2025-03-26 01:29:19'),(44,26,2,'Terima kasih, Tasya 🙏🏻',NULL,'2025-03-26 01:29:51','2025-03-26 01:29:51'),(45,40,2,'👍🏻',NULL,'2025-03-26 01:32:16','2025-03-26 01:32:16'),(46,42,99,'pagii',NULL,'2025-03-26 19:04:04','2025-03-26 19:04:04'),(47,42,99,'pgai jugaaaa',NULL,'2025-03-26 19:04:08','2025-03-26 19:04:08'),(48,42,99,'iya pagii',NULL,'2025-03-26 19:04:11','2025-03-26 19:04:11'),(49,42,108,'luarbiasa',NULL,'2025-03-26 19:07:16','2025-03-26 19:07:16'),(50,42,108,'ihihihiii',NULL,'2025-03-26 19:07:26','2025-03-26 19:07:26'),(51,42,105,'test',NULL,'2025-03-26 19:07:40','2025-03-26 19:07:40'),(52,42,118,'Pagii',NULL,'2025-03-26 19:07:51','2025-03-26 19:07:51'),(53,42,102,'pagi maryo',NULL,'2025-03-26 19:08:06','2025-03-26 19:08:06'),(54,42