INSERT INTO `quest_answers` VALUES (5,'true',1,2,1,1,NULL,'2025-03-11 19:08:36','2025-03-11 19:08:36'),(16,'C',1,7,1,1,NULL,'2025-03-13 18:24:59','2025-03-13 18:24:59'),(17,'<p>True &amp;&amp; True</p>',0,8,1,1,NULL,'2025-03-14 02:27:41','2025-03-14 02:27:41'),(18,'<p> False &amp;&amp; True</p>',1,8,1,1,NULL,'2025-03-14 02:27:41','2025-03-14 02:27:41'),(19,'<p>(3 &gt; 2) &amp;&amp; (5 &lt; 10)</p>',0,8,1,1,NULL,'2025-03-14 02:27:41','2025-03-14 02:27:41'),(20,'<p>True || False</p>',0,8,1,1,NULL,'2025-03-14 02:27:41','2025-03-14 02:27:41'),(21,'5',1,9,1,1,NULL,'2025-03-14 02:35:50','2025-03-14 02:35:50'),(22,'<p>Fungsional</p>',1,1,1,1,NULL,'2025-03-18 07:30:19','2025-03-18 07:30:19'),(23,'<p>Prosedural</p>',0,1,1,1,NULL,'2025-03-18 07:30:19','2025-03-18 07:30:19'),(24,'<p>Berorientasi Objek</p>',0,1,1,1,NULL,'2025-03-18 07:30:19','2025-03-18 07:30:19'),(25,'<p>Deklaratif</p>',0,1,1,1,NULL,'2025-03-18 07:30:19','2025-03-18 07:30:19'),(26,'<p>Prosedural</p>',0,4,1,1,NULL,'2025-03-18 07:30:47','2025-03-18 07:30:47'),(27,'<p>Fungsional</p>',0,4,1,1,NULL,'2025-03-18 07:30:47','2025-03-18 07:30:47'),(28,'<p>Deklaratif</p>',1,4,1,1,NULL,'2025-03-18 07:30:47','2025-03-18 07:30:47'),(29,'<p>Konkuren</p>',0,4,1,1,NULL,'2025-03-18 07:30:47','2025-03-18 07:30:47'),(30,'<p>Java</p>',1,10,1,1,NULL,'2025-03-18 07:33:39','2025-03-18 07:33:39'),(31,'<p>Python</p>',1,10,1,1,NULL,'2025-03-18 07:33:39','2025-03-18 07:33:39'),(32,'<p>Fortran</p>',0,10,1,1,NULL,'2025-03-18 07:33:39','2025-03-18 07:33:39'),(33,'<p>C++</p>',1,10,1,1,NULL,'2025-03-18 07:33:39','2025-03-18 07:33:39'),(62,'<ul><li><strong>Paradigma prosedural</strong> berfokus pada instruksi yang dieksekusi secara berurutan, seperti langkah-langkah dalam resep masakan. Kode tersusun dalam bentuk fungsi yang dipanggil sesuai kebutuhan.</li><li><strong>Paradigma berorientasi objek</strong> mengorganisir kode ke dalam objek yang memiliki atribut (data) dan perilaku (metode). Ini memungkinkan kode lebih modular dan mudah dikelola.</li></ul><p><br></p>',0,6,1,1,NULL,'2025-03-25 09:40:03','2025-03-25 09:40:03'),(63,'Prolog',1,5,1,1,NULL,'2025-03-25 09:40:23','2025-03-25 09:40:23'),(72,'<p>Hanya untuk memenuhi syarat kelulusan mata kuliah pemrograman.</p>',0,11,1,1,NULL,'2025-03-25 12:33:57','2025-03-25 12:33:57'),(73,'<p>Agar kita bisa mengklaim diri sebagai programmer sejati.</p>',0,11,1,1,NULL,'2025-03-25 12:33:57','2025-03-25 12:33:57'),(74,'<p>Untuk memahami lebih dalam tentang cara kerja komputer.&nbsp;</p>',0,11,1,1,NULL,'2025-03-25 12:33:57','2025-03-25 12:33:57'),(75,'<p>Agar kita dapat memilih bahasa pemrograman dan pendekatan pemecahan masalah yang tepat.&nbsp;</p>',1,11,1,1,NULL,'2025-03-25 12:33:57','2025-03-25 12:33:57'),(80,'<p>Paradigma Berorientasi Objek</p>',0,12,1,1,NULL,'2025-03-25 12:34:30','2025-03-25 12:34:30'),(81,'<p>Paradigma Prosedural</p>',0,12,1,1,NULL,'2025-03-25 12:34:30','2025-03-25 12:34:30'),(82,'<p>Paradigma Fungsional</p>',0,12,1,1,NULL,'2025-03-25 12:34:30','2025-03-25 12:34:30'),(83,'<p>Paradigma Logika</p>',1,12,1,1,NULL,'2025-03-25 12:34:30','2025-03-25 12:34:30'),(92,'<p>Memudahkan dalam membaca dan memahami kode orang lain.&nbsp;</p>',0,13,1,1,NULL,'2025-03-25 12:38:01','2025-03-25 12:38:01'),(93,'<p>Memungkinkan kita memilih bahasa pemrograman yang tepat.</p>',0,13,1,1,NULL,'2025-03-25 12:38:01','2025-03-25 12:38:01'),(94,'<p>Meningkatkan kemampuan dalam memecahkan masalah yang kompleks.</p>',0,13,1,1,NULL,'2025-03-25 12:38:01','2025-03-25 12:38:01'),(95,'<p>Membuat kita lebih cepat dalam menulis kode.</p>',1,13,1,1,NULL,'2025-03-25 12:38:01','2025-03-25 12:38:01'),(100,'<p>9, 13</p>',0,14,1,1,NULL,'2025-03-25 12:49:41','2025-03-25 12:49:41'),(101,'<p>3, 13</p>',0,14,1,1,NULL,'2025-03-25 12:49:41','2025-03-25 12:49:41'),(102,'<p>13, 3</p>',1,14,1,1,NULL,'2025-03-25 12:49:41','2025-03-25 12:49:41'),(103,'<p>13, 9</p>',0,14,1,1,NULL,'2025-03-25 12:49:41','2025-03-25 12:49:41'),(104,'<p>True &amp;&amp; True</p>',0,15,1,1,NULL,'2025-03-25 12:54:18','2025-03-25 12:54:18'),(105,'<p>not False&nbsp;</p>',0,15,1,1,NULL,'2025-03-25 12:54:18','2025-03-25 12:54:18'),(106,'<p>True || False</p>',0,15,1,1,NULL,'2025-03-25 12:54:18','2025-03-25 12:54:18'),(107,'<p>False &amp;&amp; True</p>',0,15,1,1,NULL,'2025-03-25 12:54:18','2025-03-25 12:54:18'),(108,'<p>3</p>',1,16,1,1,NULL,'2025-03-25 13:02:32','2025-03-25 13:02:32'),(109,'<p>4</p>',0,16,1,1,NULL,'2025-03-25 13:02:32','2025-03-25 13:02:32'),(110,'<p>5</p>',0,16,1,1,NULL,'2025-03-25 13:02:32','2025-03-25 13:02:32'),(111,'<p>6</p>',0,16,1,1,NULL,'2025-03-25 13:02:32','2025-03-25 13:02:32'),(112,'<p>1 / x</p>',0,17,1,1,NULL,'2025-03-25 13:11:56','2025-03-25 13:11:56'),(113,'<p>fromMaybe 0 (1 / x)</p>',0,17,1,1,NULL,'2025-03-25 13:11:56','2025-03-25 13:11:56'),(114,'<p>div 1 x</p>',0,17,1,1,NULL,'2025-03-25 13:11:56','2025-03-25 13:11:56'),(115,'<p>if x /= 0 then 1/x else 0</p>',1,17,1,1,NULL,'2025-03-25 13:11:56','2025-03-25 13:11:56'),(116,'<p>9, 13</p>',0,18,1,1,NULL,'2025-03-25 13:49:13','2025-03-25 13:49:13'),(117,'<p>3, 13</p>',0,18,1,1,NULL,'2025-03-25 13:49:13','2025-03-25 13:49:13'),(118,'<p>13, 3</p>',1,18,1,1,NULL,'2025-03-25 13:49:13','2025-03-25 13:49:13'),(119,'<p>13, 9</p>',0,18,1,1,NULL,'2025-03-25 13:49:13','2025-03-25 13:49:13'),(120,'<pre>isPrime n = if n &lt;= 1 then False\n  else all (\\x -&gt; n `mod` x /= 0) [2..n-1]\n </pre>',0,19,1,1,NULL,'2025-03-25 14:06:10','2025-03-25 14:06:10'),(121,'<pre>isPrime n = if n &lt;= 1 then False \n  else all (\\x -&gt; n `mod` x /= 0) [2..sqrt n]</pre>',0,19,1,1,NULL,'2025-03-25 14:06:11','2025-03-25 14:06:11'),(122,'<pre>isPrime n = if n &lt;= 1 then False \n  else all (\\x -&gt; n `mod` x /= 0) [2..n `div` 2]</pre>',0,19,1,1,NULL,'2025-03-25 14:06:11','2025-03-25 14:06:11'),(123,'<pre>isPrime n = if n &lt;= 1 then False \n  else all (\\x -&gt; n `mod` x /= 0) [2..n] </pre>',0,19,1,1,NULL,'2025-03-25 14:06:11','2025-03-25 14:06:11'),(124,'<pre>isKabisat :: Int -&gt; Int -&gt; Bool\nisKabisat yy\n  | yy `mod` 400 == 0                     = True\n  | yy `mod` 4 == 0 &amp;&amp; yy `mod` 100 /= 0  = True\n  | otherwise                             = False</pre>',0,20,1,1,NULL,'2025-03-25 14:09:25','2025-03-25 14:09:25'),(125,'<pre>isKabisat :: Int -&gt; Int\nisKabisat yy\n  | yy `mod` 400 == 0                     = True\n  | yy `mod` 4 == 0 &amp;&amp; yy `mod` 100 /= 0  = True\n  | otherwise                             = False</pre>',0,20,1,1,NULL,'2025-03-25 14:09:25','2025-03-25 14:09:25'),(126,'<pre>isKabisat :: Int -&gt; Bool\nisKabisat yy\n  | yy `mod` 400 == 0                     = True\n  | yy `mod` 4 == 0 &amp;&amp; yy `mod` 100 /= 0  = True\n  | otherwise                             = False</pre>',1,20,1,1,NULL,'2025-03-25 14:09:25','2025-03-25 14:09:25'),(127,'<pre>isKabisat :: Int -&gt; Bool\nisKabisat yy\nyy `mod` 400 == 0                     = True\nyy `mod` 4 == 0 &amp;&amp; yy `mod` 100 /= 0  = True\notherwise                             = False</pre>',0,20,1,1,NULL,'2025-03-25 14:09:25','2025-03-25 14:09:25'),(128,'<pre>makeDimensi3 :: Double -&gt; Double -&gt; Double -&gt; Dimensi3\nmakeDimensi3 Dimensi3 = Dimensi3 { x = x, y = y, z = z }</pre>',0,21,1,1,NULL,'2025-03-25 14:17:55','2025-03-25 14:17:55'),(129,'<pre>makeDimensi3 :: Double -&gt; Double -&gt; Double -&gt; Dimensi3\nmakeDimensi3 = Dimensi3 { x = x, y = y, z = z }</pre>',0,21,1,1,NULL,'2025-03-25 14:17:55','2025-03-25 14:17:55'),(130,'<pre>makeDimensi3 :: Double -&gt; Double -&gt; Double -&gt; Double\nmakeDimensi3 x y z = Dimensi3 { x = x, y = y, z = z }</pre>',0,21,1,1,NULL,'2025-03-25 14:17:55','2025-03-25 14:17:55'),(131,'<pre>makeDimensi3 :: Double -&gt; Double -&gt; Double -&gt; Dimensi3\nmakeDimensi3 x y z = Dimensi3 { x = x, y = y, z = z }</pre>',1,21,1,1,NULL,'2025-03-25 14:17:55','2025-03-25 14:17:55'),(132,'<p>Tipe dibentuk dengan komponen dari tipe lain</p>',0,22,1,1,NULL,'2025-03-25 14:21:33','2025-03-25 14:21:33'),(133,'<p>Tipe mengandung rekursif terhadap funsi lain</p>',0,22,1,1,NULL,'2025-03-25 14:21:33','2025-03-25 14:21:33'),(134,'<p>Tipe dapat memanggil fungsi tanpa mengembalikan nilai</p>',0,22,1,1,NULL,'2025-03-25 14:21:33','2025-03-25 14:21:33'),(135,'<p><strong>Tipe mengandung referensi terhadap diri sendiri</strong></p>',1,22,1,1,NULL,'2025-03-25 14:21:33','2025-03-25 14:21:33'),(136,'<p>Basis merupakan bagian yang menyebabkan fungsi berhenti</p>',1,23,1,1,NULL,'2025-03-25 14:23:45','2025-03-25 14:23:45'),(137,'<p>Basis mengandung call terhadap fungsi yang di defenisikan</p>',0,23,1,1,NULL,'2025-03-25 14:23:45','2025-03-25 14:23:45'),(138,'<p>Basis akan menyebabkan program selalu looping</p>',0,23,1,1,NULL,'2025-03-25 14:23:45','2025-03-25 14:23:45'),(139,'<p>Basis akan menyebabkan program tidak infite loop</p>',0,23,1,1,NULL,'2025-03-25 14:23:45','2025-03-25 14:23:45'),(140,'<p>Point</p>',1,24,1,1,NULL,'2025-03-25 14:25:46','2025-03-25 14:25:46'),(141,'<p>Pohon</p>',0,24,1,1,NULL,'2025-03-25 14:25:46','2025-03-25 14:25:46'),(142,'<p>Strings</p>',0,24,1,1,NULL,'2025-03-25 14:25:46','2025-03-25 14:25:46'),(143,'<p>Graphs</p>',0,24,1,1,NULL,'2025-03-25 14:25:46','2025-03-25 14:25:46'),(144,'<p>Semakin kompleks algoritma rekursif, semakin rendah waktu eksekusinya</p>',0,25,1,1,NULL,'2025-03-25 14:28:02','2025-03-25 14:28:02'),(145,'<p>Analisis rekurens tidak memperhitungkan kompleksitas waktu algoritma rekursif</p>',0,25,1,1,NULL,'2025-03-25 14:28:02','2025-03-25 14:28:02'),(146,'<p>Kompleksitas waktu algoritma rekursif bergantung pada base case-nya</p>',0,25,1,1,NULL,'2025-03-25 14:28:02','2025-03-25 14:28:02'),(147,'<p><strong>Semakin tinggi kompleksitas algoritma rekursif, semakin tinggi waktu eksekusinya&nbsp;</strong></p>',0,25,1,1,NULL,'2025-03-25 14:28:02','2025-03-25 14:28:02'),(148,'<p>Kuis adalah sebuah domain yang yang menerima integer dan mengembalikan integer</p>',0,26,1,1,NULL,'2025-03-25 14:31:34','2025-03-25 14:31:34'),(149,'<p>Kuis adalah sebuah fungsi utama tanpa nilai pengembalian</p>',0,26,1,1,NULL,'2025-03-25 14:31:34','2025-03-25 14:31:34'),(150,'<p>Kuis adalah konstruktor yang dibentuk dari 2 buah tipe data integer</p>',0,26,1,1,NULL,'2025-03-25 14:31:34','2025-03-25 14:31:34'),(151,'<p>Tidak ada jawaban yang tepat</p>',1,26,1,1,NULL,'2025-03-25 14:31:34','2025-03-25 14:31:34');
