INSERT INTO `take_exercises` VALUES (233,1,1,2,38,'{\"0\": {\"type\": \"multiple_choice\", \"feedback\": \"<p>Paradigma pemrograman prosedural berfokus pada eksekusi perintah secara berurutan, seperti mengikuti resep masakan. Setiap langkah dilakukan dalam urutan tertentu hingga program selesai.</p>\", \"exp_gained\": 10, \"question_id\": 1, \"point_gained\": 10, \"user_answer_id\": 328, \"correct_answer_id\": 328, \"user_answer_index\": 1, \"correct_answer_index\": 1}}',1,2,0.50,10,10,10,10,NULL,'2025-03-24 23:37:12','2025-03-24 23:37:12'),(234,1,1,2,40,'{\"0\": {\"type\": \"multiple_choice\", \"feedback\": \"<p>Paradigma pemrograman prosedural berfokus pada eksekusi perintah secara berurutan, seperti mengikuti resep masakan. Setiap langkah dilakukan dalam urutan tertentu hingga program selesai.</p>\", \"exp_gained\": 10, \"question_id\": 1, \"point_gained\": 10, \"user_answer_id\": 328, \"correct_answer_id\": 328, \"user_answer_index\": 1, \"correct_answer_index\": 1}, \"1\": {\"type\": \"multiple_answer\", \"feedback\": \"<p>Bahasa seperti C dan Pascal menerapkan paradigma prosedural karena instruksinya dieksekusi secara berurutan. Sementara itu, Java lebih dikenal sebagai bahasa berorientasi objek, dan Python mendukung banyak paradigma, termasuk prosedural, tetapi lebih sering digunakan dalam paradigma lainnya.</p>\", \"exp_gained\": 10, \"question_id\": 2, \"point_gained\": 20, \"user_answer_id\": [52, 53], \"correct_answer_id\": [52, 53], \"user_answer_index\": [1, 2], \"correct_answer_index\": [1, 2], \"user_correct_answer_id\": [52, 53]}}',2,2,1.00,20,30,20,30,NULL,'2025-03-24 23:41:54','2025-03-24 23:41:54'),(235,1,1,2,41,'{\"0\": {\"type\": \"multiple_choice\", \"feedback\": \"<p>Paradigma pemrograman prosedural berfokus pada eksekusi perintah secara berurutan, seperti mengikuti resep masakan. Setiap langkah dilakukan dalam urutan tertentu hingga program selesai.</p>\", \"exp_gained\": 10, \"question_id\": 1, \"point_gained\": 10, \"user_answer_id\": 328, 