INSERT INTO `take_quests` VALUES (2588,9,76,'{\"correct_answer\":\"5\",\"exp_gained\":20,\"feedback\":\"\\u003cp\\u003eDiketahui:\\u003c/p\\u003e\\u003cul\\u003e\\u003cli\\u003ex=7x = 7x=7\\u003c/li\\u003e\\u003cli\\u003ey=3y = 3y=3\\u003c/li\\u003e\\u003cli\\u003eEkspresi: (x div y)+(x mod y)(x \\\\text{ div } y) + (x \\\\text{ mod } y)(x div y)+(x mod y)\\u003c/li\\u003e\\u003c/ul\\u003e\\u003ch3\\u003ePerhitungan:\\u003c/h3\\u003e\\u003cp\\u003e\\u003cstrong\\u003eOperasi div\\u003c/strong\\u003e (pembagian bilangan bulat tanpa sisa)\\u003c/p\\u003e\\u003cp\\u003e7÷3=27\\u003c/p\\u003e\\u003cp\\u003eJadi, x div y=2\\u003c/p\\u003e\\u003cp\\u003e\\u003cstrong\\u003eOperasi mod\\u003c/strong\\u003e (sisa hasil bagi)\\u003c/p\\u003e\\u003cp\\u003e7 mod 3=17\\u003c/p\\u003e\\u003cp\\u003eKarena 7 dibagi 3 hasilnya 2 dengan sisa 1, maka x mod y=1.\\u003c/p\\u003e\\u003cp\\u003e\\u003cstrong\\u003ePenjumlahan hasilnya:\\u003c/strong\\u003e\\u003c/p\\u003e\\u003cp\\u003e(2)+(1)=3(2) + (1) = 3(2)+(1)=3\\u003c/p\\u003e\\u003cp\\u003eJadi, hasil dari ekspresi tersebut adalah \\u003cstrong\\u003e5.\\u003c/strong\\u003e\\u003c/p\\u003e\",\"point_gained\":1,\"question_id\":9,\"user_answer\":\"5\",\"user_answer_index\":0}',1,100,20,1,NULL,'2025-03-25 23:10:28','2025-03-25 23:10:28'),(2589,1,62,'{\"correct_answer_id\":22,\"correct_answer_index\":0,\"exp_gained\":10,\"feedback\":\"\\u003cp\\u003eParadigma \\u003cstrong\\u003efungsional\\u003c/strong\\u003e berfokus pada fungsi matematika dan menghindari perubahan langsung pada data, sehingga kode lebih bersih dan minim bug.Paradigma \\u003cstrong\\u003efungsional\\u003c/strong\\u003e berfokus pada fungsi matematika dan menghindari perubahan langsung pada data, sehingga kode lebih bersih dan minim bug.\\u003c/p\\u003e\",\"point_gained\":1,\"question_id\":1,\"user_answer_id\":22,\"user_answer_index\":0}',1,100,10,1,NULL,'2025-03-25 23:10:34','2025-03-25 23:10:34'),(2590,14,62,'{\"correct_answer_id\":102,\"correct_answer_index\":2,